-- READ ONLY. Table rows prove presence only, not CHECK/FK/index/column parity.
SELECT 'table_presence' AS kind,name,to_regclass('public.'||name) IS NOT NULL AS matches
 FROM jsonb_array_elements_text($inventory$["current_subscription_operations","current_subscription_operation_events","current_subscription_reference_claims","current_payment_batches","current_bulk_allocations","current_bulk_confirmations","current_bulk_events","current_bulk_bro_entitlements","current_bro_withdrawals","current_bro_withdrawal_lines","current_bro_withdrawal_decisions","bro_field_sms_permissions","bro_field_sms_campaigns","bro_field_sms_recipients","bro_field_sms_events"]$inventory$::jsonb) n(name)
UNION ALL SELECT 'function',e.name,COALESCE((p.oid IS NOT NULL AND p.prokind='f' AND p.pronargs=0 AND p.prorettype='pg_catalog.trigger'::regtype
 AND NOT p.proretset AND NOT p.prosecdef AND p.provolatile='v' AND NOT p.proisstrict
 AND NOT p.proleakproof AND p.proparallel='u' AND p.proconfig IS NULL AND l.lanname='plpgsql'
 AND md5(regexp_replace(replace(p.prosrc,E'\r\n',E'\n'),'^[[:space:]]+|[[:space:]]+$','','g'))=e.body_md5),false)
  FROM jsonb_to_recordset($inventory$[{"name":"guard_student_direct_history","body_md5":"06020fe5a25c579f9157746f4ba847b0"},{"name":"guard_current_bulk_scope","body_md5":"f1af32ded245bbd6ca05388de4aacee6"}]$inventory$::jsonb) AS e(name text,body_md5 text) LEFT JOIN pg_proc p ON p.oid=to_regprocedure('public.'||e.name||'()')
 LEFT JOIN pg_language l ON l.oid=p.prolang
UNION ALL SELECT 'trigger',e.name,COALESCE(t.tgenabled='O' AND t.tgtype=e.type
 AND t.tgfoid=to_regprocedure('public.'||e.fn||'()') AND NOT t.tgisinternal
 AND t.tgnargs=0 AND t.tgconstraint=0 AND t.tgqual IS NULL AND t.tgattr::text='' AND t.tgparentid=0,false)
 FROM jsonb_to_recordset($inventory$[{"name":"current_subscription_operations_history","events":"UPDATE OR DELETE","table":"current_subscription_operations","level":"ROW","fn":"guard_student_direct_history","type":27},{"name":"current_subscription_events_history","events":"UPDATE OR DELETE","table":"current_subscription_operation_events","level":"ROW","fn":"guard_student_direct_history","type":27},{"name":"current_subscription_claims_history","events":"UPDATE OR DELETE","table":"current_subscription_reference_claims","level":"ROW","fn":"guard_student_direct_history","type":27},{"name":"current_bulk_allocation_scope","events":"INSERT","table":"current_bulk_allocations","level":"ROW","fn":"guard_current_bulk_scope","type":7},{"name":"current_bulk_bro_scope","events":"INSERT","table":"current_bulk_bro_entitlements","level":"ROW","fn":"guard_current_bulk_scope","type":7},{"table":"current_payment_batches","name":"current_payment_batches_history","events":"UPDATE OR DELETE","level":"ROW","fn":"guard_student_direct_history","type":27},{"table":"current_bulk_allocations","name":"current_bulk_allocations_history","events":"UPDATE OR DELETE","level":"ROW","fn":"guard_student_direct_history","type":27},{"table":"current_bulk_confirmations","name":"current_bulk_confirmations_history","events":"UPDATE OR DELETE","level":"ROW","fn":"guard_student_direct_history","type":27},{"table":"current_bulk_events","name":"current_bulk_events_history","events":"UPDATE OR DELETE","level":"ROW","fn":"guard_student_direct_history","type":27},{"table":"current_bulk_bro_entitlements","name":"current_bulk_bro_entitlements_history","events":"UPDATE OR DELETE","level":"ROW","fn":"guard_student_direct_history","type":27},{"table":"current_bro_withdrawals","name":"current_bro_withdrawals_history","events":"UPDATE OR DELETE","level":"ROW","fn":"guard_student_direct_history","type":27},{"table":"current_bro_withdrawal_lines","name":"current_bro_withdrawal_lines_history","events":"UPDATE OR DELETE","level":"ROW","fn":"guard_student_direct_history","type":27},{"table":"current_bro_withdrawal_decisions","name":"current_bro_withdrawal_decisions_history","events":"UPDATE OR DELETE","level":"ROW","fn":"guard_student_direct_history","type":27},{"table":"bro_field_sms_permissions","name":"bro_field_sms_permissions_history","events":"UPDATE OR DELETE","level":"ROW","fn":"guard_student_direct_history","type":27},{"table":"bro_field_sms_campaigns","name":"bro_field_sms_campaigns_history","events":"UPDATE OR DELETE","level":"ROW","fn":"guard_student_direct_history","type":27},{"table":"bro_field_sms_recipients","name":"bro_field_sms_recipients_history","events":"UPDATE OR DELETE","level":"ROW","fn":"guard_student_direct_history","type":27},{"table":"bro_field_sms_events","name":"bro_field_sms_events_history","events":"UPDATE OR DELETE","level":"ROW","fn":"guard_student_direct_history","type":27}]$inventory$::jsonb) e(name text,"table" text,fn text,type int)
 LEFT JOIN pg_trigger t ON t.tgrelid=to_regclass('public.'||e."table") AND t.tgname=e.name
ORDER BY kind,name;
